/**
 * Per-printing cues (illustrator credit, copyright year, printed promo caption):
 * what separates printings whose text is identical. The table is generated by
 * scripts/scan-eval/build-cues.ts. Pure: no I/O.
 */

import cues from './generated/printingCues.json';

export interface PrintingCue { illustrator: string | null; year: string | null; caption: string | null }

export const PRINTING_CUES: Record<string, PrintingCue> = cues as Record<string, PrintingCue>;

export function cueFor(cardKey: string): PrintingCue | undefined {
  return Object.prototype.hasOwnProperty.call(PRINTING_CUES, cardKey) ? PRINTING_CUES[cardKey] : undefined;
}

export function normalizeCredit(s: string | null | undefined): string {
  return (s ?? '').toLowerCase()
    .replace(/\b(illus|illustration|illustrated by|art|artist)\b\.?:?/g, '')
    .replace(/[©®™]/g, '')
    .replace(/[^a-z0-9 ]+/g, ' ')
    .replace(/\s+/g, ' ').trim();
}

/** Two normalized credit lines name the same artist: equal, or two shared tokens of length >= 3, or one shared token when either side has only one such token. */
export function creditAgrees(a: string, b: string): boolean {
  if (!a || !b) return false;
  if (a === b) return true;
  const ta = a.split(' ').filter((t) => t.length >= 3);
  const tb = b.split(' ').filter((t) => t.length >= 3);
  const shared = ta.filter((t) => tb.includes(t)).length;
  return shared >= 2 || (shared >= 1 && Math.min(ta.length, tb.length) === 1);
}

export function normalizeCaption(s: string | null | undefined): string {
  return (s ?? '').toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
}
